CREATE DATABASE IF NOT EXISTS soy_jeancuy CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE soy_jeancuy;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin') NOT NULL DEFAULT 'admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profile(id TINYINT UNSIGNED PRIMARY KEY DEFAULT 1,display_name VARCHAR(150) NOT NULL DEFAULT 'SOY JEANCUY',headline VARCHAR(255),bio TEXT,skills TEXT,experience TEXT,location VARCHAR(160),email_public VARCHAR(190),website VARCHAR(255),github VARCHAR(255),linkedin VARCHAR(255),logo_path VARCHAR(500),avatar_path VARCHAR(500),cv_path VARCHAR(500),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT IGNORE INTO profile(id,display_name) VALUES(1,'SOY JEANCUY');
CREATE TABLE IF NOT EXISTS folders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,name VARCHAR(180) NOT NULL,description TEXT,is_public BOOLEAN NOT NULL DEFAULT FALSE,deleted_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(parent_id) REFERENCES folders(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS files(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,folder_id BIGINT UNSIGNED NULL,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(255) NOT NULL,mime_type VARCHAR(150) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,is_public BOOLEAN NOT NULL DEFAULT FALSE,deleted_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(folder_id) REFERENCES folders(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS projects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,summary VARCHAR(500),description MEDIUMTEXT,technologies JSON,cover_file_id BIGINT UNSIGNED NULL,project_url VARCHAR(500),is_public BOOLEAN NOT NULL DEFAULT FALSE,deleted_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(cover_file_id) REFERENCES files(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS credentials(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,institution VARCHAR(180),issue_date DATE,description TEXT,file_id BIGINT UNSIGNED NULL,is_public BOOLEAN NOT NULL DEFAULT FALSE,deleted_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(file_id) REFERENCES files(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS activity_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED,details VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
